{
  "items": [
    {
      "name": "Nat.choose_le_two_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ (n k : ℕ), n.choose k ≤ 2 ^ n"
    },
    {
      "name": "Nat.choose_succ_le_two_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ (n k : ℕ), (n + 1).choose k ≤ 2 ^ n"
    },
    {
      "name": "Nat.choose_le_pow_div",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semifield α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α] (r n : ℕ),\n  ↑(n.choose r) ≤ ↑n ^ r / ↑r.factorial"
    },
    {
      "name": "Finset.prod_pow_choose_succ",
      "module_name": "Mathlib.Data.Nat.Choose.Sum",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} [inst : CommMonoid M] (f : ℕ → ℕ → M) (n : ℕ),\n  ∏ i ∈ Finset.range (n + 2), f i (n + 1 - i) ^ (n + 1).choose i =\n    (∏ i ∈ Finset.range (n + 1), f i (n + 1 - i) ^ n.choose i) *\n      ∏ i ∈ Finset.range (n + 1), f (i + 1) (n - i) ^ n.choose i"
    },
    {
      "name": "norm_prod_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedCommGroup E] (s : Finset ι) {f : ι → E} {n : ι → ℝ},\n  (∀ b ∈ s, ‖f b‖ ≤ n b) → ‖∏ b ∈ s, f b‖ ≤ ∑ b ∈ s, n b"
    }
  ]
}
